41	        return EXIT_SKIP;
42	    }
43	#endif
44	    auto *data = static_cast<MrnRmwSveData *>(malloc(sizeof(MrnRmwSveData)));
45	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_SVE_COUNT * sizeof(uint64_t)));
46	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_SVE_COUNT * sizeof(uint64_t)));
47	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_SVE_COUNT * sizeof(uint64_t)));
48	    memset_random(data->srcA, MRN_RMW_SVE_COUNT * sizeof(uint64_t));
49	    memset_random(data->srcB, MRN_RMW_SVE_COUNT * sizeof(uint64_t));
50	    for (int i = 0; i < MRN_RMW_SVE_COUNT; ++i) {
51	        switch (i % 4) {
52	            case 0: data->expected[i] = data->srcA[i] + data->srcB[i]; break;
53	            case 1: data->expected[i] = data->srcA[i] - data->srcB[i]; break;
54	            case 2: data->expected[i] = data->srcA[i] ^ data->srcB[i]; break;
55	            case 3: data->expected[i] = data->srcA[i] & data->srcB[i]; break;
56	        }
57	    }
58	    test->data = data;
59	    return EXIT_SUCCESS;
60	}
