62	#if defined(__aarch64__)
63	static int mrn_rmw_dump_sve_run(struct test *test, int cpu)
64	{
65	    (void)cpu;
66	    auto *data = static_cast<MrnRmwSveData *>(test->data);
67	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_SVE_COUNT * sizeof(uint64_t)));
68	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, MRN_RMW_SVE_COUNT * sizeof(uint64_t)));
69	    const int lanes = svcntd();
