72	        for (size_t base = 0; base < MRN_RMW_SVE_COUNT; base += lanes) {
73	            /* i%4 旋转: add/sub/xor/and —— 逐 lane 相位 (i%4), 按位谓词分派:
74	             * 对整批分别计算 4 个操作的结果, 用相位谓词逐 lane 选择。
75	             * (批步进 lanes 时 base%4 不恒 0, 相位谓词按 (base+k)%4 生成) */
76	            int n = (MRN_RMW_SVE_COUNT - base < (size_t)lanes) ? (int)(MRN_RMW_SVE_COUNT - base) : lanes;
77	            svbool_t pg = svwhilelt_b64((uint64_t)0, (uint64_t)n);
78	            svuint64_t va = svld1_u64(pg, data->srcA + base);
79	            svuint64_t vb = svld1_u64(pg, data->srcB + base);
80	            /* 4 个操作的结果 */
81	            svuint64_t r_add = svadd_u64_x(pg, va, vb);
82	            svuint64_t r_sub = svsub_u64_x(pg, va, vb);
83	            svuint64_t r_eor = sveor_u64_x(pg, va, vb);
84	            svuint64_t r_and = svand_u64_x(pg, va, vb);
85	            /* 相位谓词: lane k → (base+k)%4 */
86	            uint64_t phase[8];
87	            for (int k = 0; k < n; ++k) phase[k] = (base + k) % 4;
88	            svuint64_t vphase = svld1_u64(pg, phase);
89	            svuint64_t res = svsel_u64(svcmpeq_n_u64(pg, vphase, 0), r_add,
90	                          svsel_u64(svcmpeq_n_u64(pg, vphase, 1), r_sub,
91	                          svsel_u64(svcmpeq_n_u64(pg, vphase, 2), r_eor, r_and)));
92	            /* RMW: store 到 temp, load 到 dst (向量) */
93	            svst1_u64(pg, temp + base, res);
94	            svst1_u64(pg, dst + base, svld1_u64(pg, temp + base));
95	        }
96	        if (memcmp(dst, data->expected, MRN_RMW_SVE_COUNT * sizeof(uint64_t)) != 0) {
97	            /* dump 版: 定位首错 + input/golden/actual/xor 字节分解 */
98	            for (int i = 0; i < MRN_RMW_SVE_COUNT; ++i) {
99	                if (dst[i] != data->expected[i]) {
100	                    uint64_t inputv = data->srcA[i];
101	                    uint64_t golden = data->expected[i];
102	                    uint64_t actual = dst[i];
