105	                              "a=0x%016llX b=0x%016llX golden=0x%016llX "
106	                              "actual=0x%016llX xor=0x%016llX",
107	                              i, (unsigned long long)data->srcA[i],
108	                              (unsigned long long)data->srcB[i],
109	                              (unsigned long long)golden,
110	                              (unsigned long long)actual,
111	                              (unsigned long long)xorv);
112	                    (void)inputv;
113	                    break;
114	                }
115	            }
116	            report_fail_msg("mrn_rmw_dump_sve data miscompare");
117	        }
118	    }
119	    free(dst);
120	    free(temp);
121	    return EXIT_SUCCESS;
122	}
